SELECT
    ATUAL.ORGAO,
    ANTERIOR_T.CHAVE_FOLHA_JUNHO,
    ATUAL.CHAVE_FOLHA_JULHO,
    ATUAL.MATRICULA,
    ATUAL.NOME_SERVIDOR,
    ATUAL.CPF_SERVIDOR,
    ATUAL.DATA_NASCIMENTO,
    ATUAL.DATA_ADMISSAO,
    ATUAL.ESPECIALIDADE,
    ATUAL.CARGO_EFETIVO,
    ATUAL.COD_RUBRICA_LEGADO,
    ATUAL.COD_RUBRICA,
    ATUAL.NOME_RUBRICA,
    ATUAL.VALOR_CALCULADO_JULHO,
    ANTERIOR.VALOR_CALCULADO_JUNHO,
    ATUAL.VALOR_TOTAL_RECEBIMENTO_JULHO,
    ANTERIOR_T.VALOR_TOTAL_RECEBIMENTO_JUNHO,
    ATUAL.VALOR_TOTAL_DESCONTOS_JULHO,
    ANTERIOR_T.VALOR_TOTAL_DESCONTOS_JUNHO
FROM
    (
    SELECT 
        'ADAPI' ORGAO,
        FO.CHAVE_FOLHA CHAVE_FOLHA_JULHO,
        FC.COD_INSTITUCIONAL MATRICULA,
        FC.NOME NOME_SERVIDOR,
        FC.CPF_PESSOA CPF_SERVIDOR,
        FC.DATA_NASCIMENTO,
        FC.DATA_ADMISSAO,
        FC.ESPECIALIDADE,
        FC.CARGO CARGO_EFETIVO,
        R.COD_RUBRICA_LEGADO,
        R.COD_RUBRICA,
        R.NOME_RUBRICA,
        FR.VALOR_CALCULADO VALOR_CALCULADO_JULHO,
        FC.TOTAL_VANTAGENS VALOR_TOTAL_RECEBIMENTO_JULHO,
        FC.TOTAL_DESCONTOS VALOR_TOTAL_DESCONTOS_JULHO
    FROM
        SW_ADAPI.FOLHA FO 
        JOIN SW_ADAPI.FOLHA_CONTRACHEQUE FC ON FC.ID_FOLHA = FO.ID_FOLHA
        JOIN SW_ADAPI.FOLHA_FUNC_RUBRICA FR ON FR.ID_FOLHA_FUNCIONARIO = FC.ID_FOLHA_FUNCIONARIO
        JOIN SW_PUBLICO.FOLHA_RUBRICA R ON R.ID_RUBRICA = FR.ID_RUBRICA
    WHERE 
        FO.MES = 7
        AND FO.ANO = 2026
        AND R.COD_RUBRICA_LEGADO = '828'
    ) ATUAL
    LEFT JOIN (
    SELECT
        'ADAPI' ORGAO,
        FO.CHAVE_FOLHA CHAVE_FOLHA_JUNHO,
        FC.COD_INSTITUCIONAL MATRICULA,
        FC.NOME NOME_SERVIDOR,
        FC.CPF_PESSOA CPF_SERVIDOR,
        FC.DATA_NASCIMENTO,
        FC.DATA_ADMISSAO,
        FC.ESPECIALIDADE,
        FC.CARGO CARGO_EFETIVO,
        R.COD_RUBRICA_LEGADO,
        R.COD_RUBRICA,
        R.NOME_RUBRICA,
        FR.VALOR_CALCULADO VALOR_CALCULADO_JUNHO,
        FC.TOTAL_VANTAGENS VALOR_TOTAL_RECEBIMENTO_JUNHO,
        FC.TOTAL_DESCONTOS VALOR_TOTAL_DESCONTOS_JUNHO
    FROM
        SW_ADAPI.FOLHA FO
        JOIN SW_ADAPI.FOLHA_CONTRACHEQUE FC ON FC.ID_FOLHA = FO.ID_FOLHA
        JOIN SW_ADAPI.FOLHA_FUNC_RUBRICA FR ON FR.ID_FOLHA_FUNCIONARIO = FC.ID_FOLHA_FUNCIONARIO
        JOIN SW_PUBLICO.FOLHA_RUBRICA R ON R.ID_RUBRICA = FR.ID_RUBRICA
    WHERE
        FO.MES = 6
        AND FO.ANO = 2026
        AND R.COD_RUBRICA_LEGADO = '828'
    ) ANTERIOR ON ANTERIOR.MATRICULA = ATUAL.MATRICULA AND SUBSTR(ANTERIOR.CHAVE_FOLHA_JUNHO, 9) = SUBSTR(ATUAL.CHAVE_FOLHA_JULHO, 9)
    LEFT JOIN (
    SELECT
        FC.COD_INSTITUCIONAL MATRICULA,
        FO.CHAVE_FOLHA CHAVE_FOLHA_JUNHO,
        FC.TOTAL_VANTAGENS VALOR_TOTAL_RECEBIMENTO_JUNHO,
        FC.TOTAL_DESCONTOS VALOR_TOTAL_DESCONTOS_JUNHO
    FROM
        SW_ADAPI.FOLHA FO
        JOIN SW_ADAPI.FOLHA_CONTRACHEQUE FC ON FC.ID_FOLHA = FO.ID_FOLHA
    WHERE
        FO.MES = 6
        AND FO.ANO = 2026
    ) ANTERIOR_T ON ANTERIOR_T.MATRICULA = ATUAL.MATRICULA AND SUBSTR(ANTERIOR_T.CHAVE_FOLHA_JUNHO, 9) = SUBSTR(ATUAL.CHAVE_FOLHA_JULHO, 9)
UNION ALL
